mapper.select:
SELECT * FROM gitlfs_lock
 WHERE repository_id = #{repositoryId}
   AND lock_id = #{lockId};

SELECT * FROM gitlfs_lock
 WHERE repository_id = #{repositoryId}
   AND path = #{path};

SELECT * FROM gitlfs_lock
 WHERE repository_id = #{repositoryId}
    AND path = #{path}
    AND lock_id > #{continuationToken}
 ORDER BY lock_id
 LIMIT #{limit};

mapper.delete:
DELETE FROM gitlfs_lock
 WHERE repository_id = #{repositoryId}
   AND lock_id = #{lockId};

DELETE FROM gitlfs_lock
 WHERE lock_id IN (SELECT lock_id
                     FROM gitlfs_lock
                    WHERE repository_id = #{repositoryId}
                    LIMIT #{limit});

DELETE FROM gitlfs_lock
 WHERE repository_id = #{repositoryId}
 LIMIT #{limit};
